    dashboard = Dashboard()
    # Example usage
    floor_cards = ['F46 - Wren Bench', 'F47 - HQ Claude']
    dashboard.update_floor_cards(floor_cards)
    dashboard.set_mood_avatar('happy')
    dashboard.add_to_past_window('Updated evolution gauge.')
    dashboard.display_dashboard()
